  "loc.gpsTracker": "🛰️ Rastreador GPS",
  "loc.guide1": "Instala la app <b>«Traccar Client»</b> (App Store o Google Play, gratis).",
  "loc.guide2": "En la app, introduce en <b>ID del dispositivo</b> (Device identifier):",
  "loc.guide3": "Introduce en <b>URL del servidor</b>:",
  "loc.guide4": "Precisión <b>Media</b>, distancia <b>50 m</b>. La app solo envía cuando te mueves; en reposo, nada. Si tienes más campos (intervalo, heartbeat), heartbeat desactivado o 0.",
  "loc.guide5": "Permite el acceso a la ubicación: <b>Siempre</b> y <b>Ubicación exacta</b> activada.",
  "loc.guide6": "Activa el interruptor <b>Servicio / Seguimiento</b> y <b>déjalo siempre activado</b>: listo. A partir de ahora controlas todo en pinn.: «Enviar de forma continua» sí o no, «Enviar una vez» y SOS. Mientras «Enviar de forma continua» esté desactivado, nadie ve tu ubicación y pinn. no registra ningún recorrido.",
  "loc.guideIntro": "Sin otra app, «📍 Compartir ubicación» funciona directamente en pinn., pero solo mientras pinn. está abierto. Para que la ubicación llegue también con pinn. cerrado y la pantalla bloqueada, la app gratuita «Traccar Client» la envía directamente a pinn. (no hace falta servidor Traccar). Igual en iPhone y Android.",
  "loc.h025013Watch5093": ", H02 5013, Watch 5093, Teltonika 5027. Este puerto debe redirigirse al NAS en la FRITZ!Box, porque el rastreador se conecta desde la red móvil.",
