  "smart.guide1": "1. Nuevo atajo «pinn Automatik»:",
  "smart.guide10": "El dispositivo debe poder acceder a pinn. (wifi en casa o VPN). Cada acción se ejecuta solo una vez por tarea; lo que ya se inició con el botón no lo vuelve a iniciar la automatización.",
  "smart.guide2": "• «Obtener contenido de URL» – pega el enlace de arriba",
  "smart.guide3": "• «Obtener valor del diccionario» – clave «aktionen»",
  "smart.guide4": "• «Repetir con cada elemento», dentro:",
  "smart.guide5": "– «Obtener valor del diccionario» – clave «eingabe» de «Elemento repetido»",
  "smart.guide6": "– «Obtener valor del diccionario» – clave «kurzbefehl» de «Elemento repetido»",
  "smart.guide7": "– «Ejecutar atajo» – como atajo el valor «kurzbefehl» y como entrada el valor «eingabe»",
  "smart.guide8": "2. Pestaña «Automatización» → «Hora del día» – una automatización por hora arriba, «Ejecutar inmediatamente» → «pinn Automatik».",
  "smart.guide9": "3. Consejo: además «Llegar» (Casa) → «pinn Automatik» – recupera lo que se haya perdido.",
  "smart.haAddress": "Dirección",
  "smart.haAddressHint": "Simplemente la dirección IP como la escribes en el navegador – pinn. prueba él mismo http://, https:// y el puerto (8123). «homeassistant.local» no funciona aquí, usa la IP (Home Assistant → Ajustes → Sistema → Red o en el router).",
  "smart.haAddressPh": "p. ej. 192.168.178.10",
  "smart.haChange": "Cambiar acceso",
  "smart.haConnect": "Conectar y comprobar",
  "smart.haConnectFirst": "Home Assistant aún no está conectado – conéctalo en la pestaña «Home Assistant».",
  "smart.haConnected": "✓ Conectado",
  "smart.haConnectedTo": "✓ Conectado a {place}",
  "smart.haDevices": "Dispositivos con Home Assistant: {list}",
  "smart.haIntro": "El servidor pinn. controla Home Assistant directamente – los botones funcionan en cualquier dispositivo (también Android), la automatización y «Al marcar» funcionan sin atajos. Con una entidad de estado, pinn. espera hasta que p. ej. el robot aspirador termine de verdad.",
  "smart.haNeedAddress": "Introduce la dirección.",
  "smart.haNoDevices": "Aún no hay dispositivos con Home Assistant – crea uno en la pestaña «Dispositivos» y elige «Home Assistant».",
  "smart.haNotConnected": "Home Assistant aún no está conectado.",
  "smart.haOff": "Home Assistant no conectado",
  "smart.haOn": "Home Assistant conectado",
  "smart.haSearching": "Buscando Home Assistant …",
  "smart.haTip1": "Roborock: crea el dispositivo «Robot aspirador», elige arriba el robot (vacuum.…) – pinn. carga las habitaciones del mapa. En cada acción «Limpieza de habitación» con habitaciones y modo (aspirar, aspirar y fregar, fregar). «Habitación de la tarea» usa la habitación de la limpieza del hogar – los nombres deben coincidir con la app de Roborock.",
  "smart.haTip2": "El robot sirve también de estado: la siguiente acción solo empieza cuando ha vuelto a la base.",
  "smart.haTip3": "Los scripts reciben el nombre de la habitación en la variable <span class=\"font-mono\">raum</span>; así un solo script sirve para todas las habitaciones.",
  "smart.haTip4": "Luces/LED: ajusta color y brillo directamente en la acción.",
  "smart.haTip5": "La automatización se ejecuta en el servidor cada minuto – no hace falta ninguna en el móvil.",
  "smart.haToken": "Token de acceso de larga duración",
  "smart.haTokenHint": "En Home Assistant: abajo a la izquierda en tu perfil → pestaña «Seguridad» → «Tokens de acceso de larga duración» → «Crear token» y pega la cadena completa. No hace falta escribir «Bearer» delante – pinn. lo añade (tampoco molesta). El token se queda en el servidor y nunca se envía a los dispositivos.",
